runFsSelfTest('content://com.android.externalstorage.documents/tree/primary%3ADocuments/document/primary%3ADocuments', onProgress: (p) => print('SELFTEST_PROGRESS layer=${p.layer} ok=${p.ok} skipped=${p.skipped} ms=${p.elapsedMs} detail=${p.detail}')).then((r) => print('SELFTEST_RESULT success=${r.success} layers=${r.layers.map((l) => "[${l.layer} ok=${l.ok} skipped=${l.skipped} ms=${l.elapsedMs} detail=${l.detail}]").join(" | ")}')).catchError((e) => print('SELFTEST_ERROR $e'))
